119	+    expect(issuesOf({ ...claimRules, deadlineTicks: 0 })[0]).toMatch(/^deadlineTicks:/);
120	+    expect(issuesOf({ ...claimRules, circleRadiusTiles: 0 })[0]).toMatch(/^circleRadiusTiles:/);
121	+    expect(issuesOf({ channelTicks: 200, deadlineTicks: 42_000 })[0]).toMatch(/^circleRadiusTiles:/);
122	+    expect(issuesOf({ ...claimRules, extra: 1 })).toHaveLength(1);
123	+  });
124	+
