126	+    expect(issuesOf({ ...claimRules, channelTicks: 42_000 })).toEqual([
127	+      "channelTicks: a channel of 42000 ticks cannot complete before the deadline (42000 ticks)",
128	+    ]);
129	+  });
130	+});
