144	+import { z } from "zod";
145	+import { formatIssues, type ValidationResult } from "../rules.js";
146	+import { WORLD_STEPS_PER_SECOND } from "../sailing.js";
147	+
148	+/** §5: a claim completes after holding interact this long. 0 would model §5's alternative, victory on arrival. */
149	+export const CLAIM_CHANNEL_SECONDS = 10;
150	+/** §2: the match stops 35 minutes after player control starts. */
151	+export const MATCH_DURATION_MINUTES = 35;
152	+/**
153	+ * §5's treasure circle around the final island's claim point, centre to centre. A placeholder until playtests: wider
154	+ * than a docking run (1.5 tiles), narrower than the engagement range (6 tiles), so a challenger can reach a claimer.
155	+ */
156	+export const TREASURE_CIRCLE_RADIUS_TILES = 4;
157	+
158	+/** The claim rules (§2, §5) in world ticks (20 a second) and tiles; the simulation converts tiles to sub-units. */
159	+export const claimRulesSchema = z
160	+  .strictObject({
161	+    /** World ticks of held interact that complete a claim; 0 completes it on the tick it starts. */
162	+    channelTicks: z.int().nonnegative(),
163	+    /** World ticks from player control to the match deadline. */
164	+    deadlineTicks: z.int().positive(),
165	+    circleRadiusTiles: z.int().positive(),
166	+  })
167	+  .superRefine((rules, ctx) => {
168	+    if (rules.channelTicks >= rules.deadlineTicks) {
169	+      ctx.addIssue({
170	+        code: "custom",
171	+        path: ["channelTicks"],
172	+        message: `a channel of ${rules.channelTicks} ticks cannot complete before the deadline (${rules.deadlineTicks} ticks)`,
173	+      });
174	+    }
175	+  });
176	+
177	+export type ClaimRules = z.infer<typeof claimRulesSchema>;
178	+
179	+export const claimRules: ClaimRules = {
180	+  channelTicks: CLAIM_CHANNEL_SECONDS * WORLD_STEPS_PER_SECOND,
181	+  deadlineTicks: MATCH_DURATION_MINUTES * 60 * WORLD_STEPS_PER_SECOND,
182	+  circleRadiusTiles: TREASURE_CIRCLE_RADIUS_TILES,
183	+};
184	+
185	+export function validateClaimRules(candidate: unknown): ValidationResult<ClaimRules> {
186	+  const parsed = claimRulesSchema.safeParse(candidate);
187	+  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
188	+}
