210	@@ -0,0 +1,352 @@
211	+import { describe, expect, it } from "vitest";
212	+import {
213	+  claimRules,
214	+  createClaimConfig,
215	+  createClaimState,
216	+  hashState,
217	+  replayClaim,
218	+  stepClaim,
219	+  type ClaimConfig,
220	+  type ClaimEncounter,
221	+  type ClaimEvent,
222	+  type ClaimPlayer,
223	+  type ClaimState,
224	+  type ClaimTickInput,
225	+} from "./index.js";
226	+
227	+const POINT = { x: 20_000, y: 30_000 };
228	+const config = createClaimConfig({ claimPoint: POINT });
229	+const CHANNEL = config.channelTicks;
230	+const RADIUS = config.circleRadius;
231	+
232	+/** A player who could claim: at the claim point, stopped, holding everything, connected, unprotected. */
233	+function player(id: string, change: Partial<ClaimPlayer> = {}): ClaimPlayer {
234	+  return { id, x: POINT.x, y: POINT.y, speed: 0, holdsAllTypes: true, interact: true, connected: true, protected: false, ...change };
235	+}
236	+
237	+function duel(id: string, a: string, b: string): ClaimEncounter {
238	+  return { id, playerIds: [a, b] };
239	+}
240	+
241	+/** Recursively frozen, so a step that mutated its input would throw. */
242	+function deepFreeze<T>(value: T): T {
243	+  if (typeof value === "object" && value !== null && !Object.isFrozen(value)) {
244	+    Object.freeze(value);
245	+    for (const child of Object.values(value)) deepFreeze(child);
246	+  }
247	+  return value;
248	+}
249	+
250	+type Tick = { players: ClaimPlayer[]; encounters?: ClaimEncounter[] };
251	+
252	+/** Steps one tick with frozen input and state, checking neither is changed. */
253	+function step(state: ClaimState, tick: Tick, cfg: ClaimConfig = config) {
254	+  const input: ClaimTickInput = deepFreeze({ tick: state.tick + 1, players: tick.players, encounters: tick.encounters ?? [] });
255	+  const before = hashState(deepFreeze(state));
256	+  const stepped = stepClaim(cfg, state, input);
257	+  expect(hashState(state)).toBe(before);
258	+  return stepped;
259	+}
260	+
261	+/** Steps `count` identical ticks and returns the final state and every event. */
262	+function hold(state: ClaimState, tick: Tick, count: number, cfg: ClaimConfig = config) {
263	+  const events: ClaimEvent[] = [];
264	+  let current = state;
265	+  for (let index = 0; index < count; index++) {
266	+    const stepped = step(current, tick, cfg);
267	+    current = stepped.state;
268	+    events.push(...stepped.events);
269	+  }
270	+  return { state: current, events };
271	+}
272	+
273	+const kinds = (events: readonly ClaimEvent[]) => events.map((event) => event.kind);
274	+
275	+describe("claim config", () => {
276	+  it("uses the content rules: a 200-tick channel, the treasure circle in sub-units and the minute-35 deadline", () => {
277	+    expect(config).toEqual({ claimPoint: POINT, circleRadius: claimRules.circleRadiusTiles * 256, channelTicks: 200, deadlineTick: 42_000 });
278	+    expect(createClaimConfig({ claimPoint: POINT, controlStartTick: 60 }).deadlineTick).toBe(42_060);
279	+    expect(() => createClaimConfig({ claimPoint: POINT, rules: { ...claimRules, channelTicks: -1 } })).toThrow(/invalid claim rules/);
280	+    expect(() => createClaimConfig({ claimPoint: { x: 0.5, y: 0 } })).toThrow(RangeError);
281	+    expect(() => createClaimState(config, config.deadlineTick)).toThrow(RangeError);
282	+    expect(createClaimState(config)).toEqual({ tick: 0, channel: null, result: null });
283	+  });
284	+});
285	+
286	+describe("eligibility (§5)", () => {
287	+  const start = createClaimState(config);
288	+
289	+  it("lets a player start who holds all four types inside the circle, stopped, connected and holding interact", () => {
290	+    const { state, events } = step(start, { players: [player("a")] });
291	+    expect(events).toEqual([{ kind: "claim-started", tick: 1, playerId: "a" }]);
292	+    expect(state.channel).toEqual({ playerId: "a", startTick: 1, x: POINT.x, y: POINT.y, progress: 0 });
293	+  });
294	+
295	+  it("counts the circle's edge as inside and one sub-unit beyond it as outside", () => {
296	+    expect(step(start, { players: [player("a", { x: POINT.x + RADIUS })] }).state.channel?.playerId).toBe("a");
297	+    expect(step(start, { players: [player("a", { y: POINT.y - RADIUS })] }).state.channel?.playerId).toBe("a");
298	+    expect(step(start, { players: [player("a", { x: POINT.x + RADIUS + 1 })] }).state.channel).toBeNull();
299	+    // (3r/5, 4r/5) lies exactly on the circle when r is a multiple of 5; one sub-unit further does not.
300	+    const r = RADIUS - (RADIUS % 5);
301	+    const edge = createClaimConfig({ claimPoint: POINT, rules: { ...claimRules, circleRadiusTiles: 5 }, subUnitsPerTile: r / 5 });
302	+    expect(step(start, { players: [player("a", { x: POINT.x + (3 * r) / 5, y: POINT.y + (4 * r) / 5 })] }, edge).state.channel).not.toBeNull();
303	+    expect(step(start, { players: [player("a", { x: POINT.x + (3 * r) / 5 + 1, y: POINT.y + (4 * r) / 5 })] }, edge).state.channel).toBeNull();
304	+  });
305	+
306	+  it.each<[string, Partial<ClaimPlayer>]>([
307	+    ["missing a rubbing type", { holdsAllTypes: false }],
308	+    ["moving", { speed: 1 }],
309	+    ["reversing", { speed: -1 }],
310	+    ["disconnected", { connected: false }],
311	+    ["not holding interact", { interact: false }],
312	+    ["outside the circle", { x: POINT.x - RADIUS - 1 }],
313	+  ])("refuses a player %s", (_, change) => {
314	+    const { state, events } = step(start, { players: [player("a", change)] });
315	+    expect(state.channel).toBeNull();
316	+    expect(events).toEqual([]);
317	+  });
318	+
319	+  it("refuses a player reserved for a duel", () => {
320	+    const { state, events } = step(start, { players: [player("a"), player("b", { interact: false })], encounters: [duel("e1", "a", "b")] });
321	+    expect(state.channel).toBeNull();
322	+    expect(events).toEqual([]);
323	+  });
324	+
325	+  it("ends a protected player's protection first, then starts the claim (§6)", () => {
326	+    const { state, events } = step(start, { players: [player("a", { protected: true })] });
327	+    expect(events).toEqual([
328	+      { kind: "protection-ended", tick: 1, playerId: "a" },
329	+      { kind: "claim-started", tick: 1, playerId: "a" },
330	+    ]);
331	+    expect(state.channel?.playerId).toBe("a");
332	+  });
333	+
334	+  it("keeps the protection of a protected player who must wait", () => {
335	+    const first = step(start, { players: [player("a")] }).state;
336	+    const { events } = step(first, { players: [player("a"), player("b", { protected: true })] });
337	+    expect(events).toEqual([]);
338	+  });
339	+});
340	+
341	+describe("the channel (§5)", () => {
342	+  const start = createClaimState(config);
343	+
344	+  it("completes after ten seconds of held interact: 200 ticks after the tick it starts", () => {
345	+    const almost = hold(start, { players: [player("a")] }, CHANNEL);
346	+    expect(almost.state.channel).toMatchObject({ playerId: "a", startTick: 1, progress: CHANNEL - 1 });
347	+    expect(almost.state.result).toBeNull();
348	+    const done = step(almost.state, { players: [player("a")] });
349	+    expect(done.state).toEqual({ tick: CHANNEL + 1, channel: null, result: { reason: "claim", winner: "a", tick: CHANNEL + 1 } });
350	+    expect(done.events).toEqual([
351	+      { kind: "claim-completed", tick: CHANNEL + 1, playerId: "a" },
352	+      { kind: "match-ended", tick: CHANNEL + 1, reason: "claim", winner: "a" },
353	+    ]);
354	+  });
355	+
356	+  it("runs one channel at a time: a second eligible player waits, then starts from zero when the first breaks", () => {
357	+    const both = { players: [player("a"), player("b", { x: POINT.x + 1 })] };
358	+    const first = hold(start, both, 50);
359	+    expect(first.state.channel).toMatchObject({ playerId: "a", progress: 49 });
360	+    expect(kinds(first.events)).toEqual(["claim-started"]);
361	+    const broken = step(first.state, { players: [player("a", { interact: false }), player("b", { x: POINT.x + 1 })] });
362	+    expect(broken.events).toEqual([
363	+      { kind: "claim-interrupted", tick: 51, playerId: "a", reason: "released", progress: 49 },
364	+      { kind: "claim-started", tick: 51, playerId: "b" },
365	+    ]);
366	+    // a holds interact again but b now owns the channel, which completes 200 ticks after it started.
367	+    const rest = hold(broken.state, both, CHANNEL);
368	+    expect(rest.state.result).toEqual({ reason: "claim", winner: "b", tick: 51 + CHANNEL });
369	+  });
370	+
371	+  const breaks: [string, (id: string) => ClaimPlayer | null, string][] = [
372	+    ["moving", (id) => player(id, { speed: 2 }), "moved"],
373	+    ["drifting to a new position at speed 0", (id) => player(id, { x: POINT.x + 1 }), "moved"],
374	+    ["losing a rubbing type", (id) => player(id, { holdsAllTypes: false }), "ineligible"],
375	+    ["disconnecting", (id) => player(id, { connected: false }), "disconnected"],
376	+    ["leaving the snapshot", () => null, "disconnected"],
377	+    ["releasing interact", (id) => player(id, { interact: false }), "released"],
378	+  ];
379	+
380	+  it.each(breaks)("resets progress to zero on %s", (_, broken, reason) => {
381	+    const channelled = hold(start, { players: [player("a")] }, 120).state;
382	+    const brokenPlayer = broken("a");
383	+    const interrupted = step(channelled, { players: brokenPlayer === null ? [] : [brokenPlayer] });
384	+    // A player who drifted but is still eligible where they stopped starts again at once, from zero.
385	+    expect(interrupted.state.channel === null || interrupted.state.channel.progress === 0).toBe(true);
386	+    expect(interrupted.events[0]).toEqual({ kind: "claim-interrupted", tick: 121, playerId: "a", reason, progress: 119 });
387	+    // Restarting counts from zero: the full channel again.
388	+    const restarted = hold(interrupted.state, { players: [player("a")] }, CHANNEL + 1);
389	+    expect(restarted.state.result).toEqual({ reason: "claim", winner: "a", tick: 122 + CHANNEL });
390	+  });
391	+
392	+  it("resets progress to zero when the channeller enters a duel", () => {
393	+    const channelled = hold(start, { players: [player("a"), player("b", { interact: false })] }, 120).state;
394	+    const reserved = step(channelled, { players: [player("a"), player("b", { interact: false })], encounters: [duel("e1", "b", "a")] });
