593	+/** Offsets from the claim point: several at the same distance (300), the circle's edge (1024) and outside it. */
594	+const SPOTS: readonly (readonly [number, number])[] = [
595	+  [0, 0],
596	+  [300, 0],
597	+  [0, 300],
598	+  [-300, 0],
599	+  [180, -240],
