607	+type Draw = (bound: number) => number;
608	+
609	+function generator(seed: number): Draw {
610	+  let rng = seed;
611	+  return (bound) => {
612	+    const drawn = nextInt(rng, bound);
613	+    rng = drawn.state;
614	+    return drawn.value;
615	+  };
616	+}
