618	+function shuffled<T>(items: readonly T[], draw: Draw): T[] {
619	+  const copy = [...items];
620	+  for (let index = copy.length - 1; index > 0; index--) {
621	+    const other = draw(index + 1);
622	+    [copy[index], copy[other]] = [copy[other]!, copy[index]!];
623	+  }
624	+  return copy;
625	+}
