627	+/**
628	+ * A seeded script of ticks from `start + 1` to past the deadline: players wander between spots, gain and lose their
629	+ * set, press and release interact, disconnect, gain protection, and pair off into duels that later end. `calm` (per
630	+ * mille) scales how rarely anything changes, so some scripts let a channel run to completion.
631	+ */
632	+function randomScript(seed: number, start: number, calm: number): ClaimTickInput[] {
633	+  const draw = generator(seed);
634	+  const chance = (perMille: number) => draw(1000) < Math.floor((perMille * (1000 - calm)) / 1000);
635	+  const count = 2 + draw(5);
636	+  const ids = shuffled(IDS, draw).slice(0, count);
637	+  const players = new Map<string, ClaimPlayer>();
638	+  for (const id of ids) {
639	+    const [dx, dy] = SPOTS[draw(SPOTS.length)]!;
640	+    players.set(id, { id, x: POINT.x + dx, y: POINT.y + dy, speed: 0, holdsAllTypes: draw(4) > 0, interact: draw(2) === 0, connected: true, protected: draw(3) === 0 });
641	+  }
642	+  let encounters: ClaimEncounter[] = [];
643	+  let encounterCount = 0;
644	+  const script: ClaimTickInput[] = [];
645	+  for (let tick = start + 1; tick <= config.deadlineTick + 20; tick++) {
646	+    for (const id of ids) {
647	+      let next = players.get(id)!;
648	+      if (next.speed !== 0) next = { ...next, speed: 0 };
649	+      if (chance(40)) {
650	+        const [dx, dy] = SPOTS[draw(SPOTS.length)]!;
651	+        next = { ...next, x: POINT.x + dx, y: POINT.y + dy, speed: 1 + draw(64) };
652	+      }
653	+      if (chance(20)) next = { ...next, holdsAllTypes: !next.holdsAllTypes };
654	+      if (chance(60)) next = { ...next, interact: !next.interact };
655	+      if (chance(15)) next = { ...next, connected: !next.connected };
656	+      if (chance(10)) next = { ...next, protected: !next.protected };
657	+      players.set(id, next);
658	+    }
659	+    encounters = encounters.filter(() => !chance(80));
660	+    if (chance(60)) {
