665	+        encounters = [...encounters, { id: `e${encounterCount++}`, playerIds: [a!, b!] }];
666	+      }
667	+    }
668	+    // Now and then a player drops out of the snapshot altogether.
669	+    const present = ids.filter(() => !chance(10));
670	+    script.push({ tick, players: present.map((id) => players.get(id)!), encounters });
671	+  }
672	+  return script;
673	+}
