675	+interface Run {
676	+  readonly states: readonly ClaimState[];
677	+  readonly hashes: readonly string[];
678	+  readonly events: readonly (readonly ClaimEvent[])[];
679	+}
680	+
681	+function run(cfg: ClaimConfig, start: ClaimState, script: readonly ClaimTickInput[]): Run {
682	+  const states: ClaimState[] = [];
683	+  const events: ClaimEvent[][] = [];
684	+  let state = start;
685	+  for (const input of script) {
686	+    const stepped = stepClaim(cfg, state, input);
687	+    state = stepped.state;
688	+    states.push(state);
689	+    events.push([...stepped.events]);
690	+  }
691	+  return { states, hashes: states.map(hashState), events };
692	+}
