694	+/** The same script with every tick's players and encounters in a different order. */
695	+function reorder(script: readonly ClaimTickInput[], seed: number): ClaimTickInput[] {
696	+  const draw = generator(seed);
697	+  return script.map((input) => ({ ...input, players: shuffled(input.players, draw), encounters: shuffled(input.encounters, draw) }));
698	+}
